mapper.select:
SELECT DISTINCT a.BALANCE_DATE AS balanceDate, a.FINPROD_ID AS finprodId, a.BOOKSET_ID AS booksetId, bokset.BOOKSET_NAME as booksetName, a.SUBJECT_NO AS subjectNo, subject.SUBJECT_NAME AS subjectName, a.O_CCY AS oCcy, a.O_AMT AS oAmt, a.B_CCY AS bCcy, a.B_AMT AS bAmt, a.BAL_FLAG AS balFlag FROM BOK_BANK_POSITION a LEFT JOIN BOK_BOOKSET bokset ON a.BOOKSET_ID = bokset.BOOKSET_ID INNER JOIN BOK_SUBJECT subject ON a.SUBJECT_NO = subject.SUBJECT_NO AND bokset.BOOKSET_ID_TMPL = subject.BOOKSET_ID WHERE 1=1
AND a.SUBJECT_NO = #{subjectNo}
AND a.BALANCE_DATE >=to_date(#{balanceDateBegin},'yyyy-MM-dd')
AND a.BALANCE_DATE <=to_date(#{balanceDateEnd},'yyyy-MM-dd')
AND a.FINPROD_ID IN
#{finprodId}
AND a.O_CCY IN
#{ccy}
ORDER BY a.BALANCE_DATE desc,a.FINPROD_ID asc,a.SUBJECT_NO asc

SELECT a.BALANCE_DATE as balanceDate, '' as finprodId, bokset.BOOKSET_ID AS booksetId, bokset.BOOKSET_NAME as booksetName, a.SUBJECT_NO AS subjectNo, NVL(subject.SUBJECT_NAME,bbd.DETAIL_SUBJECT_NAME) AS subjectName, a.O_CCY AS oCcy, sum(a.O_AMT) AS oAmt, a.B_CCY AS bCCy, sum(a.B_AMT) AS bAmt, a.BAL_FLAG AS balFlag, sum(a.NUM_AMT) AS numAmt FROM BOK_BANK_POSITION a LEFT JOIN BOK_BOOKSET bokset ON a.BOOKSET_ID = bokset.BOOKSET_ID LEFT JOIN BOK_SUBJECT subject ON a.SUBJECT_NO = subject.SUBJECT_NO AND bokset.BOOKSET_ID_TMPL = subject.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB bbd ON bbd.BOOKSET_ID = a.BOOKSET_ID AND bbd.DETAIL_SUBJECT_NO = a.SUBJECT_NO WHERE 1=1 AND bokset.ACCT_SUBJECT_TYPE ='BANK'
AND a.FINPROD_ID IN
#{finprodId}
AND a.SUBJECT_NO = #{subjectNo}
AND a.BALANCE_DATE >=to_date(#{bookDateBegin},'yyyy-MM-dd')
AND a.BALANCE_DATE <=to_date(#{bookDateEnd},'yyyy-MM-dd')
AND a.O_CCY IN
#{ccy}
GROUP BY a.BALANCE_DATE, bokset.BOOKSET_ID, bokset.BOOKSET_NAME, a.SUBJECT_NO, NVL(subject.SUBJECT_NAME,bbd.DETAIL_SUBJECT_NAME), a.O_CCY, a.B_CCY, a.BAL_FLAG ORDER BY a.BALANCE_DATE desc, a.SUBJECT_NO asc
